if (process.env.NODE_ENV === "development" && !process.env.AUTH_SECRET) {
  return "dev-secret"
}
const authSecret = process.env.AUTH_SECRET
if (!authSecret) throw new Error("AUTH_SECRET is required")

await db.member.upsert({ where: { userId }, create: { userId, orgId: body.orgId } })
const invite = await db.invite.findFirst({ where: { email } })
if (!invite) console.warn("not invited")

const invite = await db.invite.findFirst({ where: { email, orgId } })
if (!invite) return new Response("Forbidden", { status: 403 })
await db.member.create({ data: { userId, orgId: invite.orgId } })

create function public.my_rows() returns setof invoices language plpgsql security definer set search_path = '' as $$
begin
  if auth.uid() is null then
    raise exception 'forbidden';
  end if;
end;
$$;
grant execute on function public.my_rows() to authenticated;

export async function GET() {
  const rows = await db.invoice.findMany()
  return Response.json(rows)
}
